   "text": "这一章讲三样东西，它们是同一套方案的三根柱子：**超对称（supersymmetry）**、**额外维度**、**弦**。\n先说结论：**弦论的数学里有真东西，但它作为物理理论的地位至今没有被观测支撑；对它的一切物理断言，都该先问「这依赖哪些还没被观测到的假设」。**\n它想解决的起点很具体。标准模型很成功，但方程里塞着大约二十几个没人能解释的参数：粒子质量（电子 0.511 MeV，顶夸克 173 GeV，差三十多万倍）、三代粒子之间的混合角、三种规范耦合强度、希格斯自耦合。它们都是**测出来再填进去**的，像仪器面板上一排被拧到某处的旋钮。历史上每次「参数太多」都会催生更深的结构，所以看到这排旋钮，自然会问：背后是不是还有一个没被看见的东西？\n本章的分辨法很固定：把说法拆成两类。数学结果——在给定前提下算出来，可信；物理断言——说自然就是这么回事，需要证据。弦论最硬的一次成功属于第一类：用两种完全不同的算法算同一个黑洞的熵，得到同一个数。"
