   "orig": "把电荷、质量这样的量按 27.10 节引入的绝对（普朗克）单位来写，往往很能说明问题——在那套单位里，牛顿引力常数 G、光速 c、狄拉克形式的普朗克常数 ℏ、玻尔兹曼常数 k 统统取为 1：G = c = ℏ = k = 1。用这些单位，质子的电荷（也就是电子电荷取负）约为 e = 1/√137，更精确地是 e = 0.085 424 6；而基本夸克电荷（下夸克电荷取负，见 25.6 节）是这个值的三分之一。绝对单位通常叫普朗克单位（有时也叫普朗克–惠勒单位），缘由是量子力学的那位马克斯·普朗克（见 21.4 节）在 1906 年的一篇论文里提出过这类想法。讽刺的是，他在那篇论文里拿来定标的是电荷，而不是自己的「普朗克常数」；按他那套方案，干脆有 e = −1。（电荷之谜当然没因此消失：在他自己的方案里，ℏ = 137.036。）后来是约翰·惠勒（如 1975 年）在众多文字中反复强调这些想法的重要性——他用的是 ℏ，而不是普朗克选的电荷。",
   "notes": [
    {
     "q": "「G = c = ℏ = k = 1」",
     "a": "把四个基本常数一并设为 1，等于宣布「用自然自己的单位思考」。此后冒出的那些无量纲数（如 0.0854、4×10⁻²³）才是真正待解释的东西，而不是单位换算的副产物。"
    }
   ],
