   "orig": "超对称的基本想法，是提供一条途径，让费米子与玻色子按某种对称关系「配对」。如 25.5–8 节所见，粒子物理里通常的对称群只在玻色子集合内部「转动」玻色子，在费米子集合内部「转动」费米子；它们不会把玻色子转成费米子，也不会反过来。超对称做的恰恰是这件事。回忆 26.2 节：玻色子满足对易律，费米子满足反对易律。要把一种变成另一种，算符本身就得带反对易的性质。可普通连续群给出的算符是该群的无穷小生成元，它们凑成一个李代数（见 13.6 节）；李代数的元素满足对易律，不满足反对易律。这意味着所需的算符并不属于某个普通连续群的无穷小生成元，而属于一个更宽泛的概念——超群（supergroup）：在那里，李代数的定律被放宽，一部分生成元在对易律之外也允许满足反对易律。",
