   "orig": "我当时的反应大致是：「总该有别的绕法」——尽管我从未细究过这个问题，也就没体会到「26 维」这个结论背后推理的分量。我猜不少人的反应也差不多，理论正是在这一点上失掉了先前的一大片人气。而我自己不认 26 维宇宙模型的理由，还有一重额外的输入，来自扭量理论。我们将在 33.2、4、10 节看到，我这一套「扭量」视角有个本质性的推论：时空确实就该是我们直接观测到的一时间加三空间（即「1+3 维」）。除了这些额外维度该拿它怎么办的问题——大约要按某种卡鲁扎–克莱恩式的处方处理——这个看上去相当简单的强子弦模型还撞上了别的麻烦，比如出现了快子（tachyon）行为，也就是超光速传播。此外，第 25 章所述标准模型的节节胜利，也让物理学家对弦模型这类「跑得太远」的建议不如从前上心。前面提到的那些把韦内齐亚诺、南部等人引上弦论之路的强子物理怪现象，在胶子–夸克图景里找到了（部分的）量子色动力学替代解释。尤为要紧的是，强子组分的「点状」本性正日益在实验上显形：这与标准模型的夸克图景相符，却与当时的弦图景不符。一圈弦的典型尺度与弦的耦合强度挂钩；对最初的强子弦（其张力与强相互作用耦合常数的大小相配）来说，这给出约 10⁻¹⁵ 米的平均圈尺度。在质子的尺度上，这实在算不上「点状」——它跟质子自身的「个头」差不多。",
