   "orig": "可以拿它同弦论学家所考虑的那个具体的「黑洞」相比：后者也是「极端」的，意即霍金温度为零。但几乎所有这类弦论计算处理的都是完全另一类东西！它们没有用转动——克尔参数 a 的存在所允许的那种转动——而是引入了额外的物理场。弦论学家的「洞」是照着爱因斯坦方程的赖斯纳–努德斯特伦解（Reissner–Nordstrøm solution）来构造的，这个解与克尔解不同，是球对称的。代替克尔 a 的，是一个量度黑洞总电荷的参数 e；赖斯纳–努德斯特伦度规是爱因斯坦–麦克斯韦方程（31.4 节）的解，也就是能量–动量张量取无源麦克斯韦场的那种爱因斯坦方程。视界面积现在由一个看上去很像的公式给出：A = 8π[m + √(m² − e²)]²G²/c⁴。这个度规代表黑洞而非裸奇点的条件是 m ≥ |e|；黑洞达到极端（温度为零）的条件是 m = |e|。（绝对值符号——见 6.1 节——只是为了容许 e 取负值。）",
